remask = true;
if remask
    % Cut 1
    if ~exist('cuts2fit800GH','var')
        [msk00,~,msk800o00_vertex] = draw_mask(w2_800o00);
        cuts2fit800GH.mask_ds1 = msk800o00_vertex;
    else
        [msk00,~,msk800o00_vertex] = draw_mask(w2_800o00,'mask',cuts2fit800GH.mask_ds1');
    end
    wm800_o00 = mask(w2_800o00,msk00)
    plot(wm800_o00); lz 0 0.5; keep_figure;

    % Cut 2
    wm800_om1m1 = cut(w2_800om1m1,[0,0.04,2],[]);
    plot(wm800_om1m1); lz 0 0.5;
    if ~exist('cuts2fit800GH','var')
        [mskom1m100,~,msk800_om1m1_vertex] = draw_mask(wm800_om1m1);
        cuts2fit800GH.mask_ds2 = msk800_om1m1_vertex;
    else
        [mskom1m100,~,msk800_om1m1_vertex] = draw_mask(wm800_om1m1,'mask',cuts2fit800GH.mask_ds2');
    end
    wm800_om1m1 = mask(wm800_om1m1,mskom1m100)
    plot(wm800_om1m1); lz 0 0.5;keep_figure

    % Cut 3
    wm_800o11 = cut(w2_800o11,[-2,0.04,3],[]);
    plot(wm_800o11); lz 0 0.5;
    if ~exist('cuts2fit800GH','var')
        [msko11,~,msk800_o11_vertex] = draw_mask(wm_800o11);
        wm_800o11  = mask(wm_800o11,msko11)
        [msko11b,~,msk800_o11_vertex1] = draw_mask(wm_800o11);
        plot(wm_800o11 ); lz 0 0.5
        [msko11c,~,msk800_o11_vertex2] = draw_mask(wm_800o11);
        wm_800o11  = mask(wm_800o11,msko11c)
        plot(wm_800o11 ); lz 0 0.5; keep_figure
    else
        [msko11,~,msk800_o11_vertex] = draw_mask(wm_800o11,'mask',cuts2fit800GH.mask_ds3{1}');
        wm_800o11  = mask(wm_800o11,msko11)
        [msko11b,~,msk800_o11_vertex1] = draw_mask(wm_800o11,'mask',cuts2fit800GH.mask_ds3{2}');
        wm_800o11  = mask(wm_800o11,msko11b)
        [msko11c,~,msk800_o11_vertex2] = draw_mask(wm_800o11,'mask',cuts2fit800GH.mask_ds3{3}');
        wm_800o11  = mask(wm_800o11,msko11c)
        plot(wm_800o11 ); lz 0 0.5; keep_figure
    end

    cuts2fit800GH=struct('cuts_list',[], ...
